/**
 * `appdist build` - builds a prebuilt Expo project (ios/ and android/ already
 * generated by `expo prebuild`) with xcodebuild / Gradle, without EAS, and
 * uploads the resulting .ipa / .apk. With --aab, Android produces a signed
 * .aab for Google Play instead; that one is not uploaded, because the server
 * can only install .ipa and .apk files.
 *
 * The JS bundle only sees the variables from the env file
 * (.env.production.local by default): Expo's own .env loading is disabled
 * with EXPO_NO_DOTENV, so .env.local etc. can't leak into a release build.
 */
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { createInterface } from "node:readline";
import { parseArgs } from "node:util";

type Upload = (file: string, options: { notes?: string }) => Promise<void>;
type Env = Record<string, string | undefined>;

// xcodebuild -quiet still prints a note per target and per build setting.
const XCODE_NOISE = /^note: /;

const EXPORT_METHODS: Record<string, string> = {
  "ad-hoc": "release-testing",
  development: "debugging",
  enterprise: "enterprise",
};

export async function build(argv: string[], upload: Upload): Promise<void> {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      notes: { type: "string", short: "n" },
      "env-file": { type: "string", default: ".env.production.local" },
      "export-method": { type: "string", default: "ad-hoc" },
      "skip-upload": { type: "boolean" },
      aab: { type: "boolean" },
      verbose: { type: "boolean" },
    },
  });
  const [target] = positionals;
  if (!target || !["ios", "android", "all"].includes(target) || positionals.length > 1) {
    throw new Error("Usage: appdist build <ios|android|all> [-n notes] [--aab]");
  }
  const aab = !!values.aab;
  if (aab && target !== "android") {
    throw new Error("--aab only applies to `appdist build android`");
  }
  const exportMethod = EXPORT_METHODS[values["export-method"]];
  if (!exportMethod) throw new Error(`Unknown --export-method ${values["export-method"]}`);

  const root = process.cwd();
  if (!existsSync(join(root, "package.json"))) throw new Error(`No package.json in ${root}`);

  const envFile = resolve(root, values["env-file"]);
  if (!existsSync(envFile)) throw new Error(`Env file not found: ${envFile}`);
  const fileEnv = parseEnv(await readFile(envFile, "utf8"));
  const env: Env = {
    ...process.env,
    ...fileEnv,
    NODE_ENV: "production",
    EXPO_NO_DOTENV: "1",
  };
  log(`Using ${Object.keys(fileEnv).length} variables from ${values["env-file"]}`);

  const platforms =
    target === "all" ? (["ios", "android"] as const) : [target as "ios" | "android"];
  for (const platform of platforms) {
    if (!existsSync(join(root, platform))) {
      throw new Error(`${platform}/ not found - run \`npx expo prebuild\` first`);
    }
  }

  for (const platform of platforms) {
    const started = Date.now();
    const artifact =
      platform === "ios"
        ? await buildIos(root, env, exportMethod, !!values.verbose)
        : await buildAndroid(root, env, !!values.verbose, aab);
    log(`Built ${artifact} in ${Math.round((Date.now() - started) / 1000)}s`);
    if (aab) {
      if (values.notes) log("warning: --notes ignored - an .aab is not uploaded");
      log("Upload this bundle to Google Play Console:");
      console.log(artifact);
    } else if (!values["skip-upload"]) {
      await upload(artifact, { notes: values.notes });
    }
  }
}

async function buildIos(
  root: string,
  env: Env,
  exportMethod: string,
  verbose: boolean,
): Promise<string> {
  const iosDir = join(root, "ios");
  const workspace = (await readdir(iosDir)).find((f) => f.endsWith(".xcworkspace"));
  if (!workspace) throw new Error("No .xcworkspace in ios/ - run `npx expo prebuild` first");
  // Expo names the scheme after the workspace.
  const scheme = workspace.replace(/\.xcworkspace$/, "");

  const outDir = join(iosDir, "build", "appdist");
  const archivePath = join(outDir, `${scheme}.xcarchive`);
  const exportPath = join(outDir, "export");
  await rm(outDir, { recursive: true, force: true });
  await mkdir(outDir, { recursive: true });

  const quiet = verbose ? [] : ["-quiet"];
  log(`Archiving ${scheme} (Release)…`);
  await run(
    "xcodebuild",
    [
      "-workspace",
      join(iosDir, workspace),
      "-scheme",
      scheme,
      "-configuration",
      "Release",
      "-destination",
      "generic/platform=iOS",
      "-archivePath",
      archivePath,
      "-allowProvisioningUpdates",
      ...quiet,
      "archive",
    ],
    { cwd: iosDir, env, hide: verbose ? undefined : XCODE_NOISE },
  );

  const exportOptions = join(outDir, "ExportOptions.plist");
  await writeFile(
    exportOptions,
    `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>method</key>
  <string>${exportMethod}</string>
  <key>signingStyle</key>
  <string>automatic</string>
  <key>thinning</key>
  <string>&lt;none&gt;</string>
</dict>
</plist>
`,
  );
  log("Exporting .ipa…");
  await run(
    "xcodebuild",
    [
      "-exportArchive",
      "-archivePath",
      archivePath,
      "-exportPath",
      exportPath,
      "-exportOptionsPlist",
      exportOptions,
      "-allowProvisioningUpdates",
      ...quiet,
    ],
    { cwd: iosDir, env, hide: verbose ? undefined : XCODE_NOISE },
  );

  const ipa = (await readdir(exportPath)).find((f) => f.endsWith(".ipa"));
  if (!ipa) throw new Error(`xcodebuild did not produce an .ipa in ${exportPath}`);
  return join(exportPath, ipa);
}

async function buildAndroid(
  root: string,
  env: Env,
  verbose: boolean,
  aab: boolean,
): Promise<string> {
  const androidDir = join(root, "android");
  const outputs = join(androidDir, "app", "build", "outputs");
  const output = aab
    ? join(outputs, "bundle", "release", "app-release.aab")
    : join(outputs, "apk", "release", "app-release.apk");
  // Check signing first, so a missing setting fails before anything is deleted or built.
  const signing = androidSigning(root, env, aab);
  await rm(output, { force: true });

  const buildEnv = { ...env, ...signing };
  const hasSdkDir = existsSync(join(androidDir, "local.properties"));
  if (!buildEnv.ANDROID_HOME && !buildEnv.ANDROID_SDK_ROOT && !hasSdkDir) {
    const sdk = join(homedir(), "Library", "Android", "sdk");
    if (existsSync(sdk)) buildEnv.ANDROID_HOME = sdk;
  }

  log(aab ? "Building release AAB…" : "Building release APK…");
  // Run gradlew with bash, not its #!/bin/sh: dash (sh on Debian/Ubuntu) drops
  // variables with dots in their names, which would silently lose the signing
  // settings and leave the build signed with the debug keystore.
  await run(
    "bash",
    [
      "./gradlew",
      aab ? "app:bundleRelease" : "app:assembleRelease",
      ...(verbose ? [] : ["--quiet", "--console=plain"]),
    ],
    { cwd: androidDir, env: buildEnv, name: "gradlew" },
  );
  if (!existsSync(output)) throw new Error(`Gradle did not produce ${output}`);
  return output;
}

/**
 * Android Gradle Plugin's injected signing properties override the
 * signingConfig that prebuild generates (the debug keystore). They're returned
 * as ORG_GRADLE_PROJECT_* variables instead of -P arguments because any local
 * user can read a process's arguments with `ps`, and the passwords must stay
 * out of them.
 */
function androidSigning(root: string, env: Env, required: boolean): Env {
  const keystore = env.APPDIST_ANDROID_KEYSTORE;
  if (!keystore && !required) {
    log("warning: APPDIST_ANDROID_KEYSTORE not set - the APK is signed with the debug keystore");
    return {};
  }
  const missing = [
    "APPDIST_ANDROID_KEYSTORE",
    "APPDIST_ANDROID_KEYSTORE_PASSWORD",
    "APPDIST_ANDROID_KEY_ALIAS",
  ].filter((name) => !env[name]);
  if (missing.length) {
    throw new Error(
      `Missing ${missing.join(", ")}${required ? " - Google Play rejects an .aab signed with the debug keystore" : ""}`,
    );
  }
  const storeFile = resolve(root, keystore!);
  if (!existsSync(storeFile)) throw new Error(`Keystore not found: ${storeFile}`);
  const prefix = "ORG_GRADLE_PROJECT_android.injected.signing";
  return {
    [`${prefix}.store.file`]: storeFile,
    [`${prefix}.store.password`]: env.APPDIST_ANDROID_KEYSTORE_PASSWORD,
    [`${prefix}.key.alias`]: env.APPDIST_ANDROID_KEY_ALIAS,
    [`${prefix}.key.password`]:
      env.APPDIST_ANDROID_KEY_PASSWORD || env.APPDIST_ANDROID_KEYSTORE_PASSWORD,
  };
}

/** Minimal dotenv parser: KEY=value, `export`, quotes and # comments. */
export function parseEnv(source: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of source.split(/\r?\n/)) {
    const match = /^\s*(?:export\s+)?([\w.-]+)\s*=(.*)$/.exec(line);
    if (!match) continue;
    const [, key, rest] = match;
    const value = rest.trim();
    const quoted = /^(["'])(.*)\1(?:\s+#.*)?$/.exec(value);
    if (quoted?.[1] === '"') out[key] = quoted[2].replace(/\\n/g, "\n").replace(/\\(["\\])/g, "$1");
    else if (quoted) out[key] = quoted[2];
    // Unquoted: `#` starts a comment only after whitespace, so URLs with fragments survive.
    else out[key] = value.replace(/(^|\s+)#.*$/, "");
  }
  return out;
}

function run(
  command: string,
  args: string[],
  options: { cwd: string; env: Env; hide?: RegExp; name?: string },
): Promise<void> {
  const { hide, name = command, ...spawnOptions } = options;
  return new Promise((resolvePromise, reject) => {
    const child = spawn(command, args, {
      ...spawnOptions,
      stdio: ["ignore", hide ? "pipe" : "inherit", hide ? "pipe" : "inherit"],
    });
    if (hide) {
      for (const [stream, out] of [
        [child.stdout, process.stdout],
        [child.stderr, process.stderr],
      ] as const) {
        createInterface({ input: stream! }).on("line", (line) => {
          if (!hide.test(line)) out.write(`${line}\n`);
        });
      }
    }
    child.on("error", reject);
    child.on("close", (code, signal) => {
      if (code === 0) resolvePromise();
      else reject(new Error(`${name} failed (${signal ?? `exit code ${code}`})`));
    });
  });
}

function log(message: string): void {
  process.stderr.write(`${message}\n`);
}
